questionvariables.text:
round_prop(num) := block(if num-floor(num)<0.5 then return(floor(num)) else return(ceiling(num)));

/* Randomising lengths */
depth:rand_with_step(3,7,1);
width:rand_with_step(depth+1,depth+5,1);
height:rand_with_step(width+1,width+5,1);

/* Solutions */
tans1:sqrt((depth/2)^2 + (width/2)^2 + height^2);
tans2:(1/2)*depth*sqrt((width/2)^2 + height^2);

feedbackvariables.text:
/* Node 1: Correct solution */
/* Node 2: Worked solution */
/* Node 3: Incorrect rounding (2) */
node3_test: if abs(ans1-tans1)<=0.1 then 1 else 0;

/* Node 4: Forgets to square root answer (1) */
node4_error:(depth/2)^2+(width/2)^2+height^2;

/* Node 5: Doesn't halve width or depth (1) */
node5_errorA:sqrt(depth^2 + width^2 + height^2);
node5_errorB:sqrt((depth/2)^2 + width^2 + height^2);
node5_errorC:sqrt(depth^2 + (width/2)^2 + height^2);

node5_test: if ans1=float(round_prop(10*node5_errorA)/10) or ans1=float(round_prop(10*node5_errorA)/10) or float(round_prop(10*node5_errorA)/10) then 1 else 0;

/* Node 6: Halves height (1) */
node6_error:sqrt((depth/2)^2 + (width/2)^2 + (height/2)^2);

/* Node 7: Does any of N4-6 and also rounds incorrectly (feedback) */
node7_test: if abs(ans1-node4_error)<=0.1 or abs(ans1-node5_errorA)<=0.1 or abs(ans1-node5_errorB)<=0.1 or abs(ans1-node5_errorC)<=0.1 or abs(ans1-node6_error)<=0.1 then 1 else 0;

/* Node 1: Correct solution */
/* Node 2: Worked solution */
/* Node 3: Incorrect rounding (2) */
node3_test: if abs(ans2-tans2)<=0.1 then 1 else 0;

/* Node 4: Forgets to square root slanted height (1) */
node4_error:(1/2)*depth*((width/2)^2 + height^2),1;

/* Node 5: Doesn't halve width in slanted height calculation (1) */
node5_error: (1/2)*depth*sqrt(width^2 + height^2);

/* Node 6: Halves height in slanted height calculation (1) */
node6_error:(1/2)*depth*sqrt((width/2)^2 + (height/2)^2);

/* Node 7: Uses depth in place of width to calculate slanted height (feedback) */
node7_error:(1/2)*depth*sqrt((depth/2)^2 + height^2);

/* Node 8: Does any of N4-7 and also rounds incorrectly (feedback) */
node8_test: if abs(ans2-node4_error)<=0.1 or abs(ans2-node5_error)<=0.1 or abs(ans2-node6_error)<=0.1 or abs(ans2-node7_error)<=0.1 then 1 else 0;

/* Node 9: Calculates area using vertical height as opposed to slanted height (feedback) */
node9_test: if abs(ans2-(1/2)*depth*height)<=0.1 then 1 else 0;
